Definition win_npages : ltac2:(zQ "40!h9!jc!im4!m0>1r@2$3@1$1@1$0#k0@1$1@1$0#k0$2") := ltac2:(zQ "50!h9!jc!m0!lud!mg4\1r@2$2@1$1@1$0#k0@1$1@1$0#k0@1$4@1$3^1").

Definition win_page : ltac2:(zQ "40!h9!jc!im4!m0>1r@2$3@1$1@1$0#k0@1$1@1$0#k0>1i$2@1$1@1$0#k0") := ltac2:(zQ "a0!h9!jc!im4!m0!lre!lu5!q3!lt1!iq6!iqf\1r@2$3@1$1@1$0#k0@1$1@1$0#k0\1i$2@2$9@1$0#k0@2$6@1$5^2@2$7$4@1$8^1").

Definition win_pages : ltac2:(zQ "40!h9!jc!r5!m0>1r@2$3@1$1@1$0#k0@1$1@1$0#k0@1$2@1$1@1$0#k0") := ltac2:(zQ "80!h9!jc!im4!m0!mi4!mib!mj2!mjf\1r@2$3@1$1@1$0#k0@1$1@1$0#k0@4$4$2@1$1@1$0#k0@1$7^1@2$5N0@1$6^1").

Fixpoint all_pages (S : list (word * word)) : list word :=
  match S with
  | [] => []
  | r :: S' => win_pages r ++ all_pages S'
  end.

(* [comment removed for export] *)
Fixpoint pages_total (S : list (word * word)) : Z :=
  match S with
  | [] => 0
  | r :: S' => win_npagesZ r + pages_total S'
  end%Z.

Fixpoint wbudget (S : list (word * word)) : Z :=
  match S with
  | [] => 0
  | r :: S' => bv_unsigned (snd r) / page_size + 2 + wbudget S'
  end%Z.

